// Main: AI inference relay + IPC streaming
ipcMain.handle('ai:generate', async (event, prompt) => {
  const res = await fetch('http://localhost:8000/generate', {
    method: 'POST',
    body: JSON.stringify({ prompt }),
  });
  const reader = res.body.getReader();
  for await (const chunk of readChunks(reader)) {
    event.sender.send('ai:chunk', chunk);
  }
});

// Renderer (Angular): RxJS streaming subscription
generate(prompt: string): Observable<string> {
  ipcRenderer.invoke('ai:generate', prompt);
  return fromEvent<string>(ipcRenderer, 'ai:chunk');
}
